parameters.jsCode:
const testMode = String($env.IMMICH_MONITOR_TEST_MODE || 'false').toLowerCase() === 'true';
const now = new Date().toISOString();

function safeJson(nodeName) {
  try {
    const n = $(nodeName).first().json;
    return n && typeof n === 'object' ? n : {};
  } catch (e) {
    return { _error: true, _message: String(e?.message || e) };
  }
}

function safeText(nodeName) {
  try {
    const item = $(nodeName).first();
    if (item.json && typeof item.json === 'object' && item.json.data !== undefined) return String(item.json.data);
    // http node may put body as string in json when not parsed
    const j = item.json;
    if (typeof j === 'string') return j;
    if (j && j.res) return String(j.res);
    return JSON.stringify(j);
  } catch (e) {
    return '';
  }
}

const jobsRaw = safeJson('Get Immich Jobs');
const serverStats = safeJson('Get Immich Server Statistics');
const assetStats = safeJson('Get Immich Asset Statistics');
const storage = safeJson('Get Immich Storage');
const about = safeJson('Get Immich About');
let mlBody = '';
try {
  const ml = $('Get Immich ML Ping').first().json;
  if (typeof ml === 'string') mlBody = ml;
  else if (ml && typeof ml.data === 'string') mlBody = ml.data;
  else if (ml && ml.res) mlBody = String(ml.res);
  else mlBody = JSON.stringify(ml || '');
} catch (e) {
  mlBody = '';
}

const partial = !!(jobsRaw._error || serverStats._error || assetStats._error);

// Aggregate jobs — never include asset IDs / personal data
const jobSnapshot = {};
const failedSnapshot = {};
let backlogTotal = 0;
let failedTotal = 0;
const jobNames = [];

if (!jobsRaw._error) {
  for (const [name, info] of Object.entries(jobsRaw)) {
    if (!info || typeof info !== 'object') continue;
    const jc = info.jobCounts || {};
    const active = Number(jc.active || 0);
    const waiting = Number(jc.waiting || 0);
    const delayed = Number(jc.delayed || 0);
    const failed = Number(jc.failed || 0);
    const completed = Number(jc.completed || 0);
    const paused = Number(jc.paused || 0);
    jobSnapshot[name] = { active, waiting, delayed, failed, completed, paused, isActive: !!info.queueStatus?.isActive, isPaused: !!info.queueStatus?.isPaused };
    failedSnapshot[name] = failed;
    backlogTotal += active + waiting + delayed;
    failedTotal += failed;
    jobNames.push(name);
  }
}

const photos = Number(assetStats.images ?? serverStats.photos ?? 0);
const videos = Number(assetStats.videos ?? serverStats.videos ?? 0);
const assetCount = Number(assetStats.total ?? (photos + videos));

// Storage accessibility: Immich API returned disk fields
const storageAccessible = !storage._error && storage.diskSizeRaw != null;

// ML: ping text
let mlStatus = 'unknown';
const mlText = (mlBody || '').toLowerCase();
if (mlText.includes('pong')) mlStatus = 'ok';
else if (mlText.includes('error') || mlText === '' || mlText.includes('econn') || mlText.includes('timed')) mlStatus = 'unavailable';

const BACKLOG_THRESHOLD = 50;
const CONFIRMATIONS = 3;

let snapshot = {
  status: 'healthy',
  partial,
  test: false,
  server: {
    version: about.version || null,
    buildImage: about.buildImage || null,
  },
  assets: {
    total: assetCount,
    photos,
    videos,
    // NÃO incluir usageByUser / nomes
  },
  jobs: {
    names: jobNames,
    backlog_total: backlogTotal,
    failed_total: failedTotal,
    counts: jobSnapshot,
  },
  storage: {
    accessible: storageAccessible,
    disk_usage_percentage: storage.diskUsagePercentage ?? null,
    // raw sizes ok (não pessoal)
  },
  machine_learning: { status: mlStatus },
  problems: [],
  thresholds: {
    backlog: BACKLOG_THRESHOLD,
    confirmations: CONFIRMATIONS,
    failed_delta_warn: 5,
  },
  timestamp: now,
};

// TEST MODE fixtures — não altera Immich
if (testMode) {
  const step = Number($env.IMMICH_MONITOR_TEST_STEP || '0');
  snapshot.test = true;
  snapshot.server = { version: 'test', buildImage: 'test' };
  snapshot.assets = { total: 100, photos: 80, videos: 20 };
  snapshot.storage = { accessible: true, disk_usage_percentage: 1.0 };
  snapshot.machine_learning = { status: 'ok' };
  snapshot.jobs = {
    names: ['thumbnailGeneration', 'metadataExtraction'],
    backlog_total: 0,
    failed_total: 0,
    counts: {
      thumbnailGeneration: { active: 0, waiting: 0, delayed: 0, failed: 0, completed: 0, paused: 0 },
      metadataExtraction: { active: 0, waiting: 0, delayed: 0, failed: 0, completed: 0, paused: 0 },
    },
  };
  if (step === 1) {
    snapshot.jobs.backlog_total = 80;
    snapshot.jobs.counts.thumbnailGeneration.waiting = 80;
  } else if (step === 2) {
    snapshot.jobs.backlog_total = 80;
    snapshot.jobs.counts.thumbnailGeneration.waiting = 80;
  } else if (step === 3) {
    snapshot.jobs.backlog_total = 120;
    snapshot.jobs.counts.thumbnailGeneration.waiting = 120;
    snapshot.jobs.failed_total = 12;
    snapshot.jobs.counts.metadataExtraction.failed = 12;
  } else if (step === 4) {
    snapshot.machine_learning.status = 'unavailable';
  } else {
    // step 0 / default: healthy
  }
  snapshot.status = 'healthy'; // Evaluate ajusta
}

return [{ json: { snapshot, test_mode: testMode } }];

const snapshotWrap = $('Build Snapshot').first().json || {};
const snapshot = snapshotWrap.snapshot || {};
let previous = null;
try {
  const rows = $('Get Previous State').all().map((i) => i.json).filter(Boolean);
  previous = rows.find((r) => r.overall_status != null) || null;
  // when no rows, postgres may return empty object
  if (previous && previous.overall_status === undefined && Object.keys(previous).length === 0) previous = null;
} catch (e) {
  previous = null;
}

const now = snapshot.timestamp || new Date().toISOString();
const BACKLOG_THRESHOLD = Number(snapshot.thresholds?.backlog ?? 50);
const CONFIRMATIONS = Number(snapshot.thresholds?.confirmations ?? 3);
const FAILED_DELTA_WARN = Number(snapshot.thresholds?.failed_delta_warn ?? 5);

const prevObs = previous?.observation
  ? (typeof previous.observation === 'string' ? JSON.parse(previous.observation) : previous.observation)
  : {};
let backlogStreak = Number(prevObs.backlog_streak || 0);
let stallStreak = Number(prevObs.stall_streak || 0);
const prevFingerprint = prevObs.backlog_fingerprint || null;

let prevFailed = previous?.failed_snapshot || {};
if (typeof prevFailed === 'string') {
  try { prevFailed = JSON.parse(prevFailed); } catch (e) { prevFailed = {}; }
}

const backlog = Number(snapshot.jobs?.backlog_total || 0);
const fingerprint = JSON.stringify(
  Object.fromEntries(
    Object.entries(snapshot.jobs?.counts || {}).map(([k, v]) => [k, { a: v.active, w: v.waiting, d: v.delayed }]),
  ),
);

const problems = [];

if (snapshot.storage && snapshot.storage.accessible === false) {
  problems.push({
    code: 'storage_unavailable',
    event: 'immich_storage_unavailable',
    severity: 'error',
    message: 'Storage do Immich inacessível via API.',
  });
}

if (snapshot.machine_learning?.status === 'unavailable') {
  problems.push({
    code: 'ml_unavailable',
    event: 'immich_ml_unavailable',
    severity: 'warning',
    message: 'Immich Machine Learning indisponível (health ping).',
  });
}

if (backlog >= BACKLOG_THRESHOLD) backlogStreak += 1;
else backlogStreak = 0;

if (backlogStreak >= CONFIRMATIONS) {
  problems.push({
    code: 'job_backlog',
    event: 'immich_job_backlog',
    severity: 'warning',
    message: `Backlog de jobs Immich elevado (${backlog}) por ${backlogStreak} observações.`,
    details: { backlog_total: backlog, streak: backlogStreak, threshold: BACKLOG_THRESHOLD },
  });
}

if (backlog >= BACKLOG_THRESHOLD && prevFingerprint && prevFingerprint === fingerprint) stallStreak += 1;
else if (backlog >= BACKLOG_THRESHOLD) stallStreak = 1;
else stallStreak = 0;

if (stallStreak >= CONFIRMATIONS) {
  problems.push({
    code: 'job_stalled',
    event: 'immich_job_stalled',
    severity: stallStreak >= CONFIRMATIONS + 2 ? 'error' : 'warning',
    message: `Fila de jobs Immich aparentemente parada (${stallStreak} observações sem progresso).`,
    details: { backlog_total: backlog, streak: stallStreak },
  });
}

let failedDelta = 0;
const failedNow = snapshot.jobs?.counts || {};
for (const [name, counts] of Object.entries(failedNow)) {
  const cur = Number(counts.failed || 0);
  const old = Number(prevFailed[name] || 0);
  if (cur > old) failedDelta += cur - old;
}
if (failedDelta >= FAILED_DELTA_WARN) {
  problems.push({
    code: 'job_failures_increased',
    event: 'immich_job_failures_increased',
    severity: failedDelta >= 20 ? 'error' : 'warning',
    message: `Novas falhas de jobs Immich detectadas (+${failedDelta}).`,
    details: { failed_delta: failedDelta },
  });
}

let overall = 'healthy';
if (problems.some((p) => p.severity === 'error')) overall = 'degraded';
else if (problems.length) overall = 'attention';

snapshot.status = overall;
snapshot.problems = problems.map((p) => ({ code: p.code, event: p.event, severity: p.severity }));

const observation = {
  backlog_streak: backlogStreak,
  stall_streak: stallStreak,
  backlog_fingerprint: fingerprint,
  last_failed_totals: Object.fromEntries(
    Object.entries(failedNow).map(([k, v]) => [k, Number(v.failed || 0)]),
  ),
};

let prevProblems = previous?.problems || [];
if (typeof prevProblems === 'string') {
  try { prevProblems = JSON.parse(prevProblems); } catch (e) { prevProblems = []; }
}
const prevCodes = new Set((prevProblems || []).map((p) => p.code || p.event));

function severityRank(s) {
  return ({ info: 0, warning: 1, error: 2, critical: 3 })[s] || 0;
}

const events = [];
for (const p of problems) {
  const prevP = (prevProblems || []).find((x) => x.code === p.code);
  let reason = 'first_incident';
  let should = true;
  if (prevP) {
    if (severityRank(p.severity) > severityRank(prevP.severity || 'info')) reason = 'severity_escalated';
    else {
      reason = 'no_change';
      should = false;
    }
  }
  if (!should) continue;
  events.push({
    should_emit: true,
    source: 'immich_monitor',
    severity: p.severity,
    component: 'immich',
    event: p.event,
    status: overall,
    timestamp: now,
    message: p.message,
    details: {
      ...(p.details || {}),
      overall_status: overall,
      asset_count: snapshot.assets?.total ?? null,
      photos: snapshot.assets?.photos ?? null,
      videos: snapshot.assets?.videos ?? null,
      backlog_total: backlog,
      failed_total: snapshot.jobs?.failed_total ?? null,
      ml_status: snapshot.machine_learning?.status ?? null,
      storage_accessible: snapshot.storage?.accessible ?? null,
      notification_reason: reason,
      test: !!snapshot.test,
    },
    requires_attention: true,
    suggested_action:
      p.code === 'ml_unavailable'
        ? 'Verificar container immich_machine_learning (sem restart automático).'
        : p.code === 'storage_unavailable'
          ? 'Verificar mounts /srv/storage/fotos/immich.'
          : 'Observar filas Immich; não cancelar jobs automaticamente.',
    correlation_id: `immich:${p.code}`,
  });
}

if (previous && prevCodes.size > 0 && problems.length === 0) {
  events.push({
    should_emit: true,
    source: 'immich_monitor',
    severity: 'info',
    component: 'immich',
    event: 'immich_recovered',
    status: 'healthy',
    timestamp: now,
    message: 'Immich voltou ao estado funcional saudável.',
    details: {
      previous_problem: [...prevCodes].join(','),
      recovery_time: now,
      overall_status: 'healthy',
      test: !!snapshot.test,
      notification_reason: 'recovered',
    },
    requires_attention: false,
    suggested_action: null,
    correlation_id: 'immich:recovered',
  });
}

const persist = {
  overall_status: overall,
  asset_count: snapshot.assets?.total ?? null,
  photos: snapshot.assets?.photos ?? null,
  videos: snapshot.assets?.videos ?? null,
  job_snapshot: snapshot.jobs?.counts || {},
  failed_snapshot: Object.fromEntries(
    Object.entries(snapshot.jobs?.counts || {}).map(([k, v]) => [k, Number(v.failed || 0)]),
  ),
  backlog_total: backlog,
  ml_status: snapshot.machine_learning?.status ?? null,
  storage_accessible: snapshot.storage?.accessible ?? null,
  problems: snapshot.problems,
  observation,
  test_mode: !!snapshot.test,
  timestamp: now,
};

return [
  {
    json: {
      should_emit: events.length > 0,
      events,
      persist,
      snapshot_status: overall,
      events_count: events.length,
    },
  },
];

const data = $json;
const persist = data.persist;
const events = Array.isArray(data.events) ? data.events : [];
if (!events.length) {
  return [{ json: { should_emit: false, persist, skip_event: true } }];
}
return events.map((ev) => ({ json: { ...ev, persist, skip_event: false } }));

